def lone_shapes(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    shapes = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '#' or seen[r][c]:
                continue
            seen[r][c] = True
            stack = [(r, c)]
            cells = []
            while stack:
                i, j = stack.pop()
                cells.append((i - r, j - c))
                for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= a < rows and 0 <= b < cols and grid[a][b] == '#' and not seen[a][b]:
                        seen[a][b] = True
                        stack.append((a, b))
            shapes.append(frozenset(cells))
    counts = {}
    for s in shapes:
        counts[s] = counts.get(s, 0) + 1
    return sum(1 for s in shapes if counts[s] == 1)

